def normalize_name(name):
    result = []
    capitalize_next = True
    for ch in name:
        if ch.isalpha():
            if capitalize_next:
                result.append(ch.upper())
                capitalize_next = False
            else:
                result.append(ch.lower())
        else:
            result.append(ch)
            if ch in "-'":
                capitalize_next = True
    return ''.join(result)

