import sys

def main():
    valid_count = 0
    invalid_count = 0
    confirmed_value = 0.0
    price_sum = 0.0

    try:
        with open('seed_orders.txt', 'r') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    for line in lines:
        if not line.strip():
            continue
        parts = line.split(',')
        if len(parts) != 4:
            invalid_count += 1
            continue
        name = parts[0].strip()
        qty_str = parts[1].strip()
        price_str = parts[2].strip()
        flag = parts[3].strip()

        try:
            qty = int(qty_str)
        except ValueError:
            invalid_count += 1
            continue

        try:
            price = float(price_str)
        except ValueError:
            invalid_count += 1
            continue

        if qty <= 0 or price < 0 or flag not in ('Y', 'N'):
            invalid_count += 1
            continue

        valid_count += 1
        price_sum += price
        if flag == 'Y':
            confirmed_value += qty * price

    if valid_count > 0:
        avg_price = price_sum / valid_count
    else:
        avg_price = 0.0

    print(f"Valid: {valid_count}")
    print(f"Invalid: {invalid_count}")
    print(f"Confirmed value: {confirmed_value:.2f}")
    print(f"Average price: {avg_price:.2f}")

if __name__ == "__main__":
    main()

