import sys

def main():
    filename = "shifts.txt"
    valid_count = 0
    invalid_count = 0
    totals = {"E5": 0.0, "E10": 0.0, "Diesel": 0.0}
    pump_totals = {i: 0.0 for i in range(1, 7)}

    try:
        with open(filename, "r") as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split(",")
        if len(parts) != 4:
            invalid_count += 1
            continue
        shift_id, pump_str, litres_str, grade = [p.strip() for p in parts]

        try:
            pump = int(pump_str)
        except ValueError:
            invalid_count += 1
            continue

        try:
            litres = float(litres_str)
        except ValueError:
            invalid_count += 1
            continue

        if not (1 <= pump <= 6):
            invalid_count += 1
            continue
        if litres < 0:
            invalid_count += 1
            continue
        if grade not in ("E5", "E10", "Diesel"):
            invalid_count += 1
            continue

        valid_count += 1
        totals[grade] += litres
        pump_totals[pump] += litres

    total_litres = totals["E5"] + totals["E10"] + totals["Diesel"]

    busiest_pump = 1
    best = pump_totals[1]
    for p in range(2, 7):
        if pump_totals[p] > best:
            best = pump_totals[p]
            busiest_pump = p

    print(f"Valid entries: {valid_count}")
    print(f"E5: {totals['E5']:.2f}")
    print(f"E10: {totals['E10']:.2f}")
    print(f"Diesel: {totals['Diesel']:.2f}")
    print(f"Total litres: {total_litres:.2f}")
    print(f"Busiest pump: {busiest_pump}")
    print(f"Invalid entries: {invalid_count}")

if __name__ == "__main__":
    main()

