def main():
    try:
        with open('tips.txt', 'r') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    records = []
    for line in lines:
        parts = line.split()
        if len(parts) == 4:
            oid, method, amount, table = parts
            records.append((oid, method, int(amount), int(table)))

    n = len(records)
    total = sum(r[2] for r in records)
    card_total = sum(r[2] for r in records if r[1] == 'card')
    cash_total = sum(r[2] for r in records if r[1] == 'cash')

    table_counts = {t: 0 for t in range(1, 5)}
    table_sums = {t: 0 for t in range(1, 5)}
    for r in records:
        t = r[3]
        if t in table_counts:
            table_counts[t] += 1
            table_sums[t] += r[2]

    max_amount = -1
    max_id = ""
    for r in records:
        if r[2] > max_amount:
            max_amount = r[2]
            max_id = r[0]

    print(f"Tips: {n}")
    print(f"Total: ${total/100:.2f}")
    print(f"Card total: ${card_total/100:.2f}")
    print(f"Cash total: ${cash_total/100:.2f}")
    for t in range(1, 5):
        print(f"Table {t}: {table_counts[t]} tips, ${table_sums[t]/100:.2f}")
