from itertools import product

needed = {1, 3, 5}

valid_routes = []
for decisions in product([0, 1], repeat=4):
    watered = set()
    for i, d in enumerate(decisions):
        if d:
            watered.add(i + 1)
    watered.add(5)
    if needed.issubset(watered):
        valid_routes.append(watered)

n = len(valid_routes)
always_set = set.intersection(*valid_routes) if valid_routes else set()
union_set = set()
for r in valid_routes:
    union_set |= r
sometimes_set = union_set - always_set

print(f"valid routes: {n}")
if always_set:
    print("beds always watered: " + " ".join(str(b) for b in sorted(always_set)))
else:
