for i in range(R):
    for j in range(C):
        v = grid[i][j]
        neigh = []
        if i > 0: neigh.append(grid[i-1][j])
        if i < R-1: neigh.append(grid[i+1][j])
        if j > 0: neigh.append(grid[i][j-1])
        if j < C-1: neigh.append(grid[i][j+1])
        if all(v > n for n in neigh): peaks += 1
        if all(v < n for n in neigh): valleys += 1
        climb[i][j] = sum(max(0, n - v) for n in neigh)
maxc = -1
mr = mc = 0
for i in range(R):
    for j in range(C):
        if climb[i][j] > maxc:
            maxc = climb[i][j]
